// PDF page -> PNG rendering, isolated in its own module since mupdf is WASM
// and we want a single place to swap it out if needed.
let mupdfModule: any = null;
async function getMupdf() {
    if (!mupdfModule) {
        mupdfModule = await import('mupdf');
    }
    return mupdfModule;
}

export interface PctRect {
    x: number;
    y: number;
    width: number;
    height: number;
}

const MAX_HITS_PER_NEEDLE_PER_PAGE = 5;

// Normalize typographic/prime quote variants -> plain ASCII equivalents.
// PDFs generated by CAD tools (e.g. AutoCAD, SmartPlant) frequently encode
// the inch-mark in pipe tags as a double prime (″ U+2033) or right double
// quotation mark (" U+201D) instead of the ASCII double-quote (") stored in
// the database asset_name.  Applying this to both sides of the comparison
// makes the search resilient to that encoding mismatch.
function normalizeQuotes(s: string): string {
    return s
        // double-quote variants -> "
        .replace(/[\u201C\u201D\u201E\u201F\u2033\u2036\u275D\u275E\uFF02]/g, '"')
        // single-quote / apostrophe / prime variants -> '
        .replace(/[\u2018\u2019\u201A\u201B\u2032\u2035\u0060\uFF07]/g, "'");
}

// Extract full text layer from each page of a PDF document using mupdf.
export async function extractPdfTextByPage(buffer: Buffer): Promise<{ page_no: number; text: string }[]> {
    const { Document } = await getMupdf();
    const doc = Document.openDocument(buffer, 'application/pdf');
    try {
        const pageCount = doc.countPages();
        const results: { page_no: number; text: string }[] = [];
        for (let pageNumber = 1; pageNumber <= pageCount; pageNumber++) {
            const page = doc.loadPage(pageNumber - 1);
            try {
                const st = page.toStructuredText();
                let pageText = '';
                try {
                    pageText = normalizeQuotes(st.asText() || '');
                } finally {
                    st.destroy();
                }
                results.push({
                    page_no: pageNumber,
                    text: pageText,
                });
            } finally {
                page.destroy();
            }
        }
        return results;
    } finally {
        doc.destroy();
    }
}

// the document, returning hit locations as page-relative percentages (same
// coordinate system as rbi_pfd_asset_map.rect_x/y/width/height) so results
// plug straight into the existing tag rect fields.
export async function searchPdfText(buffer: Buffer, needles: { key: string; text: string }[]): Promise<{ key: string; page_no: number; rect: PctRect }[]> {
    const { Document } = await getMupdf();
    const doc = Document.openDocument(buffer, 'application/pdf');
    try {
        const pageCount = doc.countPages();
        const hits: { key: string; page_no: number; rect: PctRect }[] = [];
        for (let pageNumber = 1; pageNumber <= pageCount; pageNumber++) {
            const page = doc.loadPage(pageNumber - 1);
            try {
                const bounds = page.getBounds();
                const pageWidth = bounds[2] - bounds[0];
                const pageHeight = bounds[3] - bounds[1];
                if (pageWidth <= 0 || pageHeight <= 0) continue;

                const st = page.toStructuredText();
                let pageText = '';
                try {
                    pageText = normalizeQuotes(st.asText() || '').toLowerCase();
                } finally {
                    st.destroy();
                }

                // Collapse whitespace once per page for the pre-check (see below).
                const pageTextCollapsed = pageText.replace(/\s+/g, '');

                for (const needle of needles) {
                    const normalizedNeedle = normalizeQuotes(needle.text);
                    const needleTextLower = normalizedNeedle.toLowerCase();

                    // Pre-check: collapse all whitespace on both sides so that a needle
                    // whose text happens to be split across two PDF text blocks (and thus
                    // separated by a newline in asText()) is not incorrectly skipped.
                    // page.search() handles cross-block matches correctly; we just need
                    // the pre-check to not produce false negatives.
                    const needleCollapsed = needleTextLower.replace(/\s+/g, '');
                    if (!pageTextCollapsed.includes(needleCollapsed)) {
                        continue;
                    }

                    // page.search returns one Quad[] per match (a match can span
                    // several word-quads, e.g. a needle containing a space) -
                    // union all quads within a match into a single bounding rect.
                    // Use the normalized form so mupdf also gets ASCII quotes.
                    const matches = page.search(normalizedNeedle, MAX_HITS_PER_NEEDLE_PER_PAGE);
                    for (const matchQuads of matches) {
                        if (matchQuads.length === 0) continue;
                        let minX = Infinity;
                        let maxX = -Infinity;
                        let minY = Infinity;
                        let maxY = -Infinity;
                        for (const quad of matchQuads) {
                            const xs = [quad[0], quad[2], quad[4], quad[6]];
                            const ys = [quad[1], quad[3], quad[5], quad[7]];
                            minX = Math.min(minX, ...xs);
                            maxX = Math.max(maxX, ...xs);
                            minY = Math.min(minY, ...ys);
                            maxY = Math.max(maxY, ...ys);
                        }
                        minX -= bounds[0];
                        maxX -= bounds[0];
                        minY -= bounds[1];
                        maxY -= bounds[1];
                        hits.push({
                            key: needle.key,
                            page_no: pageNumber,
                            rect: {
                                x: (minX / pageWidth) * 100,
                                y: (minY / pageHeight) * 100,
                                width: ((maxX - minX) / pageWidth) * 100,
                                height: ((maxY - minY) / pageHeight) * 100,
                            },
                        });
                    }
                }
            } finally {
                page.destroy();
            }
        }
        return hits;
    } finally {
        doc.destroy();
    }
}

export async function renderPdfPageToPng(buffer: Buffer, pageNumber: number, targetWidth = 1400): Promise<Buffer> {
    const { Document, Matrix, ColorSpace } = await getMupdf();
    const doc = Document.openDocument(buffer, 'application/pdf');
    try {
        const page = doc.loadPage(pageNumber - 1);
        try {
            const bounds = page.getBounds();
            const pageWidth = bounds[2] - bounds[0];
            const scale = targetWidth / pageWidth;
            const pixmap = page.toPixmap(Matrix.scale(scale, scale), ColorSpace.DeviceRGB, false);
            try {
                return Buffer.from(pixmap.asPNG());
            } finally {
                pixmap.destroy();
            }
        } finally {
            page.destroy();
        }
    } finally {
        doc.destroy();
    }
}